draw:
var g = 9.8;
var th = p.angle * Math.PI / 180;
var tn = Math.tan(th);
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1.5;

var vdes = Math.sqrt(p.radius * g * tn);
var denMax = 1 - p.mu * tn;
var vmax = denMax <= 0.001 ? 1e9 : Math.sqrt(p.radius * g * (tn + p.mu) / denMax);
var numMin = tn - p.mu;
var vmin = numMin <= 0 ? 0 : Math.sqrt(p.radius * g * numMin / (1 + p.mu * tn));

var slip = 0;
if (p.speed > vmax) slip = 1;
else if (p.speed < vmin) slip = -1;

// cross-section of the bank
var baseY = H * 0.60;
var leftX = W * 0.10, apexX = W * 0.70;
var run = apexX - leftX;
var rise = run * tn;
if (rise > H * 0.34) { rise = H * 0.34; run = tn > 0 ? rise / tn : run; apexX = leftX + run; }
ctx.strokeStyle = C.rule;
ctx.fillStyle = C.faint;
ctx.beginPath();
ctx.moveTo(leftX, baseY); ctx.lineTo(apexX, baseY); ctx.lineTo(apexX, baseY - rise);
ctx.closePath(); ctx.fill(); ctx.stroke();

var drift = slip === 0 ? 0 : slip * 22 * (0.5 + 0.5 * Math.sin(t * 2.4));
var frac = 0.55 + drift / (run + 1);
if (frac > 0.95) frac = 0.95;
if (frac < 0.10) frac = 0.10;
var fx = leftX + run * frac;
var fy = baseY - (fx - leftX) * tn;

ctx.save();
ctx.translate(fx, fy);
ctx.rotate(-th);
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.roundRect(-18, -14, 36, 14, 3); ctx.fill();
ctx.fillStyle = C.paper;
ctx.beginPath(); ctx.roundRect(-9, -12, 12, 7, 2); ctx.fill();
ctx.restore();

// friction arrow along the surface, drawn only when friction is doing work
var ux = Math.cos(th), uy = -Math.sin(th);
var need = p.speed * p.speed / p.radius;
var fsign = (need * Math.cos(th) > g * Math.sin(th)) ? -1 : 1;  // +1 = up the slope
var flen = 34;
var ax0 = fx, ay0 = fy + 3;
ctx.strokeStyle = C.accent; ctx.fillStyle = C.accent;
ctx.beginPath();
ctx.moveTo(ax0, ay0);
ctx.lineTo(ax0 + ux * flen * fsign, ay0 + uy * flen * fsign);
ctx.stroke();
var aa = Math.atan2(uy * fsign, ux * fsign);
var tipx = ax0 + ux * flen * fsign, tipy = ay0 + uy * flen * fsign;
ctx.beginPath();
ctx.moveTo(tipx, tipy);
ctx.lineTo(tipx - 7 * Math.cos(aa - 0.4), tipy - 7 * Math.sin(aa - 0.4));
ctx.lineTo(tipx - 7 * Math.cos(aa + 0.4), tipy - 7 * Math.sin(aa + 0.4));
ctx.closePath(); ctx.fill();
ctx.fillStyle = C.accent;
ctx.textAlign = fsign > 0 ? "left" : "right";
ctx.fillText("friction", tipx + 6 * fsign, tipy + 14);

ctx.textAlign = "left";
ctx.fillStyle = C.ink;
ctx.fillText(String.fromCharCode(952) + " = " + p.angle.toFixed(0) + String.fromCharCode(176) + ",  r = " + p.radius.toFixed(0) + " m,  " + String.fromCharCode(956) + " = " + p.mu.toFixed(2), leftX, H * 0.12);
if (slip > 0) ctx.fillText("too fast: sliding up and off the bank", leftX, H * 0.12 + 16);
else if (slip < 0) ctx.fillText("too slow: sliding down toward the axis", leftX, H * 0.12 + 16);
else ctx.fillText("holds the curve", leftX, H * 0.12 + 16);

// speed number line with the safe band shaded
var gy = H * 0.86, gx0 = W * 0.08, gx1 = W * 0.92;
var vTop = 60;
function sx(v) { var q = v / vTop; if (q > 1) q = 1; return gx0 + (gx1 - gx0) * q; }
ctx.fillStyle = C.faint;
ctx.fillRect(sx(vmin), gy - 12, sx(vmax > vTop ? vTop : vmax) - sx(vmin), 24);
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(gx0, gy); ctx.lineTo(gx1, gy); ctx.stroke();
ctx.strokeStyle = C.figure;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(sx(vdes), gy - 14); ctx.lineTo(sx(vdes), gy + 14); ctx.stroke();
ctx.setLineDash([]);
ctx.strokeStyle = C.accent;
ctx.lineWidth = 2.5;
ctx.beginPath(); ctx.moveTo(sx(p.speed), gy - 16); ctx.lineTo(sx(p.speed), gy + 16); ctx.stroke();
ctx.lineWidth = 1.5;
ctx.fillStyle = C.ink;
ctx.textAlign = "center";
ctx.fillText("safe band of speeds (m/s)", (gx0 + gx1) / 2, gy - 20);
ctx.textAlign = "left";
ctx.fillText("0", gx0 - 3, gy + 26);
ctx.textAlign = "right";
ctx.fillText(vTop + " m/s", gx1, gy + 26);
ctx.textAlign = "center";
ctx.fillStyle = C.figure;
ctx.fillText("design", sx(vdes), gy + 26);

ctx.textAlign = "left";
var maxTxt = vmax > 1e8 ? "no upper limit" : vmax.toFixed(1) + " m/s";
out.note = "design speed " + vdes.toFixed(1) + " m/s   |   safe from " + vmin.toFixed(1) + " m/s to " + maxTxt + "   |   you are at " + p.speed.toFixed(1) + " m/s";
